class Live2DComponent {
    constructor() {
        this.coreLoaded = false;
    }

    async mount(container) {
        // 展示 Loading 状态
        showSpinner(container);

        // 异步获取核心库
        await loadScript('path/to/live2dcubismcore.min.js');
